module TopModule (
    input  clock,
    input  a,
    output reg p,
    output reg q
);
    reg t = 0;

    always @(posedge clock) begin
        if (a) begin
            t <= ~t;
        end
    end

    always @(*) begin
        if (clock) begin
            p = a;
            q = t;
        end else begin
            p = t;
            q = t;
        end
    end

endmodule

