module TopModule (
    input  logic clock,
    input  logic a,
    output logic p,
    output logic q
);
    logic [1:0] shift_reg;

    always_ff @(posedge clock or negedge clock) begin
        shift_reg <= {shift_reg[0], a};
    end

    assign p = shift_reg[1];
    assign q = shift_reg[0];

endmodule

module TopModule (
    input  logic clock,
    input  logic a,
    output logic p,
    output logic q
);
    logic p_reg, q_reg;

    always_ff @(posedge clock) begin
        p_reg <= a;
        q_reg <= p_reg;
    end

    assign p = p_reg;
    assign q = q_reg;

endmodule

